package app.noir.mobile;
import android.app.*;
import android.content.Intent;
import android.graphics.Rect;
import android.graphics.Typeface;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;
final class DiscoverSheet {
 static {String[][] words={{"Full page ›","الصفحة الكاملة ›"},{"Title preview","معاينة العنوان"},{"Close preview","إغلاق المعاينة"},{"Swipe down to close","اسحب للأسفل للإغلاق"},{"Loading details…","جارٍ تحميل التفاصيل…"},{"No synopsis available.","لا يتوفر ملخص."},{"Add to My List","إضافة إلى قائمتي"},{"Add to library","إضافة إلى المكتبة"},{"Log","تسجيل المشاهدة"},{"Details unavailable. Open the full page to retry.","التفاصيل غير متاحة. افتح الصفحة الكاملة للمحاولة مجددًا."}};for(String[] p:words)Loc.AR.put(p[0],p[1]);}
 final Activity a;final Dialog dialog;final NoirSheet sheet;final LinearLayout content;final DiscoveryClient client;JSONObject title;int revision=0;volatile boolean closed=false;DiscoveryClient.ArtRequest artwork;java.util.concurrent.Future<?> detailsRequest;final DataStore.WorkCancel detailsCancel=new DataStore.WorkCancel();
 static void show(Activity a,JSONObject seed,View source){new DiscoverSheet(a,DataStore.copy(seed),source);}
 DiscoverSheet(Activity activity,JSONObject seed,View source){a=activity;title=seed;client=new DiscoveryClient(a);sheet=new NoirSheet(a,seed.optString("name"),null);dialog=sheet.dialog;content=sheet.body;sheet.closeButton("Close preview");dialog.setOnDismissListener(d->{closed=true;revision++;if(artwork!=null)artwork.cancel();detailsCancel.cancel();if(detailsRequest!=null)detailsRequest.cancel(true);PhoneStream.interactive.purge();});paint(false);sheet.show();load();}
 int dp(float n){return Math.round(n*a.getResources().getDisplayMetrics().density);}
 TextView text(String value,float size,int color){TextView v=new TextView(a);v.setText(Loc.t(value));v.setTextSize(size);v.setTextColor(color);v.setPadding(0,dp(7),0,dp(7));return v;}
 void full(){a.startActivity(new Intent(a,DiscoverActivity.class).putExtra("title",title.toString()));}
 void paint(boolean loaded){if(artwork!=null)artwork.cancel();int view=++revision;content.removeAllViews();String url=title.optString("background",title.optString("poster"));ImageView art=new ImageView(a);art.setScaleType(ImageView.ScaleType.CENTER_CROP);art.setBackground(MainActivity.bg(Motion.placeholder(url),dp(14)));art.setClipToOutline(true);LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,dp(PhoneDensity.pick(150,180)));ap.bottomMargin=dp(8);content.addView(art,ap);java.util.function.BooleanSupplier valid=()->!closed&&!a.isDestroyed()&&view==revision;artwork=DiscoveryClient.load(art,NoirApp.data.images,valid,()->client.art(url,valid),bitmap->{Motion.remember(url,bitmap);Motion.loaded(art,bitmap,url);HomeLayout.tint(art,url);});sheet.setTitle(title.optString("name"));List<String> facts=new ArrayList<>();for(String value:new String[]{title.optString("releaseInfo"),title.optString("runtime"),title.optString("imdbRating").isEmpty()?"":"★ "+title.optString("imdbRating")+" IMDb"})if(!value.isEmpty())facts.add(value);for(Object value:HomeLayout.jsonValues(title.optJSONArray("genres")))if(facts.size()<6)facts.add(Loc.t(String.valueOf(value)));sheet.setSubtitle(String.join(" · ",facts));String description=title.optString("description");sheet.note(description.isEmpty()?loaded?"No synopsis available.":"Loading details…":description);boolean ready=loaded&&(title.optString("noirType").equals("movie")||DiscoveryClient.episodes(title).stream().anyMatch(DiscoveryClient::released));
  // One primary action pinned under the list; the rest stay quiet.
  if(!PhoneExperience.trackerOnly(NoirApp.data)){View stream=sheet.footerPrimary("Stream","Stream",()->perform("stream"));stream.setEnabled(ready);stream.setAlpha(ready?1:.45f);quiet("Download to phone",false,ready,()->perform("download"));}else sheet.footer(null,null,null,null);
  quiet("Add to My List",false,ready,()->perform("list"));quiet("Log",false,true,()->a.startActivity(new Intent(a,LogActivity.class).putExtra("imdb",title.optString("id")).putExtra("query",title.optString("name"))));quiet("Full page ›",true,true,this::full);}
 void quiet(String label,boolean gold,boolean enabled,Runnable run){TextView v=sheet.link(label,gold,true,run);v.setEnabled(enabled);v.setAlpha(enabled?1:.45f);}
 void load(){JSONObject seed=title;try{detailsRequest=PhoneStream.interactive.submit(()->{DataStore.workCancel.set(detailsCancel);try{JSONObject details=client.details(seed);a.runOnUiThread(()->{if(!closed&&!a.isDestroyed()){title=details;paint(true);}});}catch(Exception e){a.runOnUiThread(()->{if(!closed&&!a.isDestroyed())sheet.note("Details unavailable. Open the full page to retry.");});}finally{DataStore.workCancel.remove();}});}catch(java.util.concurrent.RejectedExecutionException e){sheet.note("Details unavailable. Open the full page to retry.");}}

 void perform(String kind){try{JSONObject selected=null,first=null;List<JSONObject> values=PhoneSeasonPlan.discoverItems(title);if(kind.equals("stream")){for(JSONObject value:values)if(value.optBoolean("movie")||DataStore.date(value.optString("airsAt"))<=System.currentTimeMillis()){selected=NoirApp.data.rememberPhoneItem(value);first=selected;break;}}else for(JSONObject saved:NoirApp.data.rememberPhoneItems(values)){if(first==null)first=saved;if(selected==null&&(saved.optBoolean("movie")||DataStore.date(saved.optString("airsAt"))<=System.currentTimeMillis()))selected=saved;}if(first==null)return;if(kind.equals("list")){JSONObject op=NoirApp.data.operation(first.optString("id"),"list");DataStore.put(op,"value",true);NoirApp.data.queue(op);NoirApp.data.syncSoon();Toast.makeText(a,Loc.t("Saved to My List"),Toast.LENGTH_SHORT).show();}else if(selected!=null){if(kind.equals("stream")){PhoneStream.start(a,selected,false);DataStore captured=NoirApp.data;captured.network.execute(()->captured.rememberPhoneItems(values));}else PhoneDownloadsActivity.open(a,selected,false);}}catch(Exception e){Toast.makeText(a,Loc.t("Details unavailable. Open the full page to retry."),Toast.LENGTH_LONG).show();}}
}
